import 'package:cloud_firestore/cloud_firestore.dart';
class Loan { final String id, memberId; final double amount, interest, balance; final DateTime issueDate,dueDate; const Loan({required this.id,required this.memberId,required this.amount,required this.interest,required this.issueDate,required this.dueDate,required this.balance}); factory Loan.fromMap(String id, Map<String,dynamic> m)=>Loan(id:id,memberId:m['memberId']??'',amount:(m['amount']??0).toDouble(),interest:(m['interest']??0).toDouble(),issueDate:(m['issueDate'] as Timestamp?)?.toDate()??DateTime.now(),dueDate:(m['dueDate'] as Timestamp?)?.toDate()??DateTime.now(),balance:(m['balance']??0).toDouble()); Map<String,dynamic> toMap()=>{'memberId':memberId,'amount':amount,'interest':interest,'issueDate':Timestamp.fromDate(issueDate),'dueDate':Timestamp.fromDate(dueDate),'balance':balance}; @override String toString()=> 'Loan TZS $amount • balance TZS $balance'; }
